/*
 * MST_$GET_PRIVATE_SIZE - count the mapped private segments of an ASID
 *
 * Original address: 0x00E44AAE (SAU2 map: MST_$GET_PRIVATE_SIZE at E44AAE)
 * Size: 246 bytes (0x00E44AAE .. 0x00E44BA3)
 * Generated by: Claude Opus 5.5
 *
 * Caller: ASKNODE_$INTERNET_INFO request 0x4B (0x00E65434).  Frame
 * (link.w A6,-0x1C; D2-D7/A2/A5 saved; A5 = 0xE7CF0C, MST_UNWIRED, unused):
 *   (0x08,A6) asid_p, (0x0C) size_ret, (0x10) rw_size_ret, (0x14) status;
 *   (-0x1C) the end of the scan (first MST slot + 4).
 *
 * Blocks:
 *   0x00E44ABC-0x00E44AD0  *asid_p above 0x39: status_$reference_to_
 *                          illegal_address, nothing else written
 *   0x00E44AD4-0x00E44AFC  first MST slot of the ASID (MST_ASID_BASE),
 *                          ML_$LOCK(MST_LOCK_ASID), end = first + 4
 *   0x00E44B00-0x00E44B76  for each of the four MST slots holding a page-
 *                          table page, the page's 64 MSTEs: an entry with a
 *                          nonzero UID high longword and bit 14 of its word
 *                          at +0x0A clear counts once, and again in the
 *                          second count when its protection ((byte +0x0A &
 *                          0x3E) >> 1, & 7) is 3
 *   0x00E44B78-0x00E44B98  unlock; both counts times 32 (KB of 32 KB
 *                          segments); status 0
 *
 * The page-table page of MST slot n lives at MST_PAGE_TABLE_BASE +
 * (MST[n] - 1) * 0x400 (the `-0x400` displacements at 0x00E44B38 and
 * 0x00E44B3E), the one-based numbering mst_$va_to_pte documents.
 */

#include "mst/mst_internal.h"
#include "ml/ml.h"

/* `cmpi.w #0x39,(A0)` 0x00E44AC0 */
#define MST_PRIV_SIZE_MAX_ASID      0x39
/* `addq.l #0x4,D0` 0x00E44AFA: MST slots per address space scanned */
#define MST_PRIV_SIZE_SLOTS         4
/* `moveq #0x3f,D1` + dbf 0x00E44B20: MSTEs per page-table page */
#define MST_PRIV_SIZE_ENTRIES       64
/* `btst.l #0xe,D6` 0x00E44B42 */
#define MST_PRIV_SIZE_SKIP_BIT      0x4000
/* `cmpi.w #0x3,D7w` 0x00E44B56 */
#define MST_PRIV_SIZE_RW_PROT       3
/* `lsl.l #0x5` 0x00E44B84 / 0x00E44B8C */
#define MST_PRIV_SIZE_KB_SHIFT      5

void MST_$GET_PRIVATE_SIZE(uint16_t *asid_p, uint32_t *size_ret,
                           uint32_t *rw_size_ret, status_$t *status_ret)
{
    uint32_t count;         /* D2 */
    uint32_t rw_count;      /* D3 */
    uint16_t slot;          /* D5w */
    uint32_t end;           /* (-0x1C,A6) */
    uint32_t page_va;
    mste_t *mste;
    int16_t i;

    /* 0x00E44ABC-0x00E44AD0 */
    if (*asid_p > MST_PRIV_SIZE_MAX_ASID) {
        *status_ret = status_$reference_to_illegal_address;
        return;
    }

    /* 0x00E44AD4-0x00E44AFC */
    slot = MST_ASID_BASE[*asid_p];
    count = 0;
    rw_count = 0;
    ML_$LOCK(MST_LOCK_ASID);
    end = (uint32_t)slot + MST_PRIV_SIZE_SLOTS;

    /* 0x00E44B00-0x00E44B76 */
    for (; (uint32_t)slot < end; slot++) {
        if (MST[slot] == 0) {
            continue;
        }
        page_va = MST_PAGE_TABLE_BASE + (uint32_t)MST[slot] * 0x400u - 0x400u;
        for (i = 0; i < MST_PRIV_SIZE_ENTRIES; i++) {
            mste = (mste_t *)ARCH_VA_TO_PTR(page_va + (uint32_t)i * 0x10u);
            if (mste->uid.high == 0) {
                continue;
            }
            if ((mste->unknown_0a & MST_PRIV_SIZE_SKIP_BIT) != 0) {
                continue;
            }
            count++;
            if (((((mste->unknown_0a >> 8) & 0x3Eu) >> 1) & 7u) ==
                MST_PRIV_SIZE_RW_PROT) {
                rw_count++;
            }
        }
    }

    /* 0x00E44B78-0x00E44B98 */
    ML_$UNLOCK(MST_LOCK_ASID);
    *size_ret = count << MST_PRIV_SIZE_KB_SHIFT;
    *rw_size_ret = rw_count << MST_PRIV_SIZE_KB_SHIFT;
    *status_ret = status_$ok;
}
